package com.zest.products.product; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.data.domain.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ProductServiceTest { @Mock ProductRepository repo; @InjectMocks ProductService service; @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);} @Test void createSavesAuditedProduct(){when(repo.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(new ProductDtos.ProductRequest("Coffee",List.of(new ProductDtos.ItemRequest(2))),"admin");assertEquals("Coffee",result.productName());assertEquals("admin",result.createdBy());assertEquals(1,result.items().size());verify(repo).save(any(Product.class));} @Test void missingProductThrowsNotFound(){when(repo.findById(9L)).thenReturn(Optional.empty());assertThrows(NoSuchElementException.class,()->service.find(9L));} }
